-- Rebuild Medina Book 3 lesson 1 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 3-17.
-- Verbatim source_text was mechanically extracted from the matching DOC edition and checked against the PDF.

begin;

do $migration$
declare
  old_rule_count integer;
  new_rule_count integer;
  source_count integer;
begin
  select count(*) into old_rule_count
  from public.rules
  where course_name = 'Мединский курс (Том 3)' and lesson_number = '1';

  if old_rule_count <> 10 then
    raise exception 'Expected 10 generated Book 3 lesson 1 rules, found %', old_rule_count;
  end if;

  delete from public.rule_sections
  where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '1');

  delete from public.rule_sources
  where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '1');

  delete from public.rules
  where course_name = 'Мединский курс (Том 3)' and lesson_number = '1';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar) values
('Мединский курс (Том 3)', '1', 'الإِعْرَابُ وَالْبِنَاءُ فِي الْأَسْمَاءِ (изменяемость и неизменяемость имён)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الاِسْمُ إِمَّا <span class="ar-tone-structure">مُعْرَبٌ</span> يَتَغَيَّرُ آخِرُهُ بِسَبَبِ الْعَامِلِ، وَإِمَّا <span class="ar-tone-structure">مَبْنِيٌّ</span> يَلْزَمُ آخِرُهُ حَالَةً وَاحِدَةً.</span><p class="rule-study-text">У <span class="ar-inline ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ الْمُعْرَبُ</span> окончание меняется из-за управляющего фактора. У <span class="ar-inline ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ الْمَبْنِيُّ</span> окончание не меняется, даже когда меняется синтаксическая роль.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Сравнение на примерах шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">состояние</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ الْمُعْرَبُ</span><span class="rule-table-ru">изменяемое имя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ الْمَبْنِيُّ</span><span class="rule-table-ru">неизменяемое имя</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительное состояние</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُ.</span><span class="rule-table-ru">Преподаватель пришёл.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ هَؤُلَاءِ.</span><span class="rule-table-ru">Эти пришли.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительное состояние</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَأَلْتُ الْمُدَرِّسَ.</span><span class="rule-table-ru">Я спросил преподавателя.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ هَؤُلَاءِ.</span><span class="rule-table-ru">Я увидел этих.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительное состояние</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى الْمُدَرِّسِ.</span><span class="rule-table-ru">Я поприветствовал преподавателя.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى هَؤُلَاءِ.</span><span class="rule-table-ru">Я поприветствовал этих.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как называется состояние</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">مَرْفُوعٌ، مَنْصُوبٌ، مَجْرُورٌ</span><span class="rule-term-ru">Так говорят об изменяемом имени.</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">فِي مَحَلِّ رَفْعٍ، فِي مَحَلِّ نَصْبٍ، فِي مَحَلِّ جَرٍّ</span><span class="rule-term-ru">Так говорят о неизменяемом имени.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор трёх форм</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">الْمُدَرِّسُ: فَاعِلٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ.</span><span class="rule-example-ru">«Преподаватель» — подлежащее глагольного предложения в رَفْعٌ; признак — дамма.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">الْمُدَرِّسَ: مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ.</span><span class="rule-example-ru">«Преподавателя» — прямое дополнение в نَصْبٌ; признак — фатха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">الْمُدَرِّسِ: اسْمٌ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ.</span><span class="rule-example-ru">«Преподавателя» — имя после предлога в جَرٌّ; признак — касра.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">هَؤُلَاءِ: مَبْنِيٌّ عَلَى الْكَسْرِ فِي مَحَلِّ رَفْعٍ أَوْ نَصْبٍ أَوْ جَرٍّ.</span><span class="rule-example-ru">Форма هَؤُلَاءِ остаётся неизменной; меняется только её синтаксическое место.</span></div></div></div></div>', 1, 'rule', 'У изменяемого имени окончание меняется под действием управляющего фактора; у неизменяемого форма окончания сохраняется.', 'الاِسْمُ إِمَّا مُعْرَبٌ يَتَغَيَّرُ آخِرُهُ بِسَبَبِ الْعَامِلِ، وَإِمَّا مَبْنِيٌّ يَلْزَمُ آخِرُهُ حَالَةً وَاحِدَةً. يُقَالُ فِي الْمُعْرَبِ: مَرْفُوعٌ أَوْ مَنْصُوبٌ أَوْ مَجْرُورٌ، وَفِي الْمَبْنِيِّ: فِي مَحَلِّ رَفْعٍ أَوْ نَصْبٍ أَوْ جَرٍّ.'),
('Мединский курс (Том 3)', '1', 'الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الْأَسْمَاءِ (изменяемые и неизменяемые имена)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَسْمَاءُ كُلُّهَا مُعْرَبَةٌ إِلَّا ثَمَانِيَ فِئَاتٍ ذَكَرَهَا الشَّارِحُ.</span><p class="rule-study-text">По общему правилу имена изменяемы. Ниже полностью сохранены восемь групп исключений и оговорённые автором особые формы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Восемь групп неизменяемых имён</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِئَةُ</span><span class="rule-table-ru">группа</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الاِسْتِثْنَاءُ</span><span class="rule-table-ru">исключение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-table-ru">местоимения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا، نَحْنُ، أَنْتَ، هُوَ، إِيَّايَ</span><span class="rule-table-ru">я, мы, ты, он, меня</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَا اسْتِثْنَاءَ</span><span class="rule-table-ru">исключения не указаны</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَسْمَاءُ الْإِشَارَةِ</span><span class="rule-table-ru">указательные имена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا، هَذِهِ، هَؤُلَاءِ، ذَلِكَ، تِلْكَ، أُولَئِكَ</span><span class="rule-table-ru">этот, эта, эти, тот, та, те</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَانِ، هَاتَانِ</span><span class="rule-table-ru">изменяются как двойственное число</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَسْمَاءُ الْمَوْصُولَةُ</span><span class="rule-table-ru">относительные имена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الَّذِي، الَّتِي، الَّذِينَ، اللَّاتِي</span><span class="rule-table-ru">который, которая, которые</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّذَانِ، اللَّتَانِ</span><span class="rule-table-ru">изменяются как двойственное число</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَسْمَاءُ الاِسْتِفْهَامِ</span><span class="rule-table-ru">вопросительные имена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ، مَا، أَيْنَ، مَتَى، كَيْفَ</span><span class="rule-table-ru">кто, что, где, когда, как</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَيٌّ</span><span class="rule-table-ru">изменяемое имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَسْمَاءُ الشَّرْطِ</span><span class="rule-table-ru">условные имена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ، مَا، مَهْمَا، أَيْنَمَا، مَتَى، حَيْثُمَا</span><span class="rule-table-ru">кто бы, что бы, что бы ни, где бы, когда бы, где бы ни</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَيٌّ</span><span class="rule-table-ru">изменяемое имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَعْضُ الظُّرُوفِ</span><span class="rule-table-ru">некоторые обстоятельственные имена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِذْ، إِذَا، أَيَّانَ، مَتَى، قَطُّ، الْآنَ، أَمْسِ، بَيْنَمَا، حَيْثُ، هُنَا، هُنَاكَ، أَيْنَ، ثَمَّ</span><span class="rule-table-ru">когда в прошлом; когда в будущем; когда; когда; когда-либо/никогда; сейчас; вчера; в то время как; где; здесь; там; где; там</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">отдельного исключения здесь нет</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَعْدَادُ الْمُرَكَّبَةُ</span><span class="rule-table-ru">составные числительные</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِنْ أَحَدَ عَشَرَ إِلَى تِسْعَةَ عَشَرَ</span><span class="rule-table-ru">от одиннадцати до девятнадцати</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اثْنَا عَشَرَ، اثْنَتَا عَشْرَةَ</span><span class="rule-table-ru">первая часть 12 изменяется как двойственное число</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَسْمَاءُ الْأَفْعَالِ</span><span class="rule-table-ru">имена глаголов</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَيْهَاتَ، أُفٍّ، آمِينَ، صَهْ</span><span class="rule-table-ru">далеко; выражение досады; аминь; замолчи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">замещают глагол по времени, смыслу и управлению</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Слитные местоимения из таблицы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمِيرُ الرَّفْعِ</span><span class="rule-table-ru">местоимение رَفْعٌ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِثَالُهُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمِيرُ النَّصْبِ وَالْجَرِّ</span><span class="rule-table-ru">местоимение نَصْبٌ / جَرٌّ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِثَالُهُ</span><span class="rule-table-ru">пример и смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَاءُ الْفَاعِلِ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">подвижная та исполнителя</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبْتُ، ذَهَبْتَ، ذَهَبْتِ</span><span class="rule-table-ru">я ушёл; ты ушёл; ты ушла</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span><span class="rule-table-ru">я говорящий</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَأَلَنِي؛ لِي؛ كِتَابِي</span><span class="rule-table-ru">он спросил меня; мне; моя книга</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ</span><span class="rule-table-ru">вау мужского множественного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبُوا</span><span class="rule-table-ru">они, мужчины, ушли</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَافُ الْمُخَاطَبِ</span><span class="rule-table-ru">каф собеседника</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَأَلَكَ؛ لَكَ؛ كِتَابُكَ</span><span class="rule-table-ru">он спросил тебя; тебе; твоя книга</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَاءُ الْمُخَاطَبَةِ</span><span class="rule-table-ru">йа обращения к женщине</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَذْهَبِينَ</span><span class="rule-table-ru">ты, женщина, уходишь</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَاءُ الْغَائِبِ</span><span class="rule-table-ru">ха отсутствующего</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَأَلَهُ، سَأَلَهَا؛ لَهُ؛ كِتَابُهُ</span><span class="rule-table-ru">спросил его/её; ему; его книга</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَلِفُ الاِثْنَيْنِ</span><span class="rule-table-ru">алиф двойственного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبَا</span><span class="rule-table-ru">они двое ушли</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَا الْمُتَكَلِّمِينَ</span><span class="rule-table-ru">на говорящих</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَأَلَنَا؛ لَنَا؛ كِتَابُنَا</span><span class="rule-table-ru">спросил нас; нам; наша книга</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نُونُ النِّسْوَةِ</span><span class="rule-table-ru">нун женского множественного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبْنَ</span><span class="rule-table-ru">они, женщины, ушли</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">нет отдельной формы в этих столбцах</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَا الْمُتَكَلِّمِينَ</span><span class="rule-table-ru">на говорящих</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبْنَا</span><span class="rule-table-ru">мы ушли</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">нет отдельной формы в этих столбцах</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Раздельные местоимения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرُّتْبَةُ</span><span class="rule-table-ru">лицо</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمَائِرُ الرَّفْعِ</span><span class="rule-table-ru">местоимения رَفْعٌ</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمَائِرُ النَّصْبِ</span><span class="rule-table-ru">местоимения نَصْبٌ</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُتَكَلِّمُ</span><span class="rule-table-ru">говорящий</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا، نَحْنُ</span><span class="rule-table-ru">я, мы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيَّايَ، إِيَّانَا</span><span class="rule-table-ru">меня, нас</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُخَاطَبُ</span><span class="rule-table-ru">собеседник</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتَ، أَنْتِ، أَنْتُمَا، أَنْتُمْ، أَنْتُنَّ</span><span class="rule-table-ru">ты м.; ты ж.; вы двое; вы мужчины; вы женщины</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيَّاكَ، إِيَّاكِ، إِيَّاكُمَا، إِيَّاكُمْ، إِيَّاكُنَّ</span><span class="rule-table-ru">тебя м.; тебя ж.; вас двоих; вас мужчин; вас женщин</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْغَائِبُ</span><span class="rule-table-ru">отсутствующий</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُوَ، هِيَ، هُمَا، هُمْ، هُنَّ</span><span class="rule-table-ru">он; она; они двое; они мужчины; они женщины</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيَّاهُ، إِيَّاهَا، إِيَّاهُمَا، إِيَّاهُمْ، إِيَّاهُنَّ</span><span class="rule-table-ru">его; её; их двоих; их мужчин; их женщин</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Составные числительные</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ أَحَدَ عَشَرَ طَالِبًا.</span><span class="rule-example-ru">Пришли одиннадцать студентов.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">رَأَيْتُ ثَلَاثَةَ عَشَرَ طَالِبًا.</span><span class="rule-example-ru">Я увидел тринадцать студентов.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">سَلَّمْتُ عَلَى تِسْعَةَ عَشَرَ طَالِبًا.</span><span class="rule-example-ru">Я поприветствовал девятнадцать студентов.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">أَسْلَمَتْ أَرْبَعَ عَشْرَةَ امْرَأَةً.</span><span class="rule-example-ru">Ислам приняли четырнадцать женщин.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ الطَّالِبُ الثَّالِثَ عَشَرَ.</span><span class="rule-example-ru">Пришёл тринадцатый студент.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ اثْنَا عَشَرَ طَالِبًا. رَأَيْتُ اثْنَيْ عَشَرَ طَالِبًا. سَلَّمْتُ عَلَى اثْنَيْ عَشَرَ طَالِبًا.</span><span class="rule-example-ru">Пришли двенадцать студентов; я увидел и поприветствовал двенадцать студентов.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">أَسْلَمَتْ اثْنَتَا عَشْرَةَ طَالِبَةً.</span><span class="rule-example-ru">Ислам приняли двенадцать студенток.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три вида имён глаголов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اسْمُ فِعْلٍ مَاضٍ</span><span class="rule-table-ru">имя прошедшего глагола</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَيْهَاتَ، شَتَّانَ</span><span class="rule-table-ru">примеры</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَعُدَ، افْتَرَقَ</span><span class="rule-table-ru">отдалилось; разделилось</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اسْمُ فِعْلٍ مُضَارِعٍ</span><span class="rule-table-ru">имя настоящего глагола</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أُفٍّ، آهِ</span><span class="rule-table-ru">примеры</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَتَضَجَّرُ، أَتَوَجَّعُ</span><span class="rule-table-ru">я досадую; мне больно</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اسْمُ فِعْلِ أَمْرٍ</span><span class="rule-table-ru">имя повелительного глагола</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">آمِينَ، صَهْ</span><span class="rule-table-ru">примеры</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اسْتَجِبْ، اسْكُتْ</span><span class="rule-table-ru">ответь; замолчи</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'Шарх перечисляет восемь групп неизменяемых имён и отдельно отмечает изменяемые исключения.', 'الْأَسْمَاءُ كُلُّهَا مُعْرَبَةٌ إِلَّا الضَّمَائِرَ، وَأَسْمَاءَ الْإِشَارَةِ، وَالْأَسْمَاءَ الْمَوْصُولَةَ، وَأَسْمَاءَ الاِسْتِفْهَامِ وَالشَّرْطِ، وَبَعْضَ الظُّرُوفِ، وَالْأَعْدَادَ الْمُرَكَّبَةَ، وَأَسْمَاءَ الْأَفْعَالِ؛ فَهَذِهِ مَبْنِيَّةٌ مَعَ الاِسْتِثْنَاءَاتِ الَّتِي ذَكَرَهَا الشَّارِحُ.'),
('Мединский курс (Том 3)', '1', 'عَلَامَاتُ الْإِعْرَابِ الْأَصْلِيَّةُ وَالْفَرْعِيَّةُ (основные и второстепенные признаки إِعْرَابٌ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">عَلَامَاتُ الْإِعْرَابِ إِمَّا <span class="ar-tone-structure">أَصْلِيَّةٌ</span> وَإِمَّا <span class="ar-tone-structure">فَرْعِيَّةٌ</span>.</span><p class="rule-study-text">Признак выбирается не только по состоянию имени, но и по его типу: единственное число, двойственное, правильное множественное или одно из пяти имён.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Основные признаки</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَسْمَاءُ</span><span class="rule-table-ru">какие имена</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الضَّمَّةُ عَلَامَةُ رَفْعٍ</span><span class="rule-table-ru">дамма — رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ، وَجَمْعُ التَّكْسِيرِ، وَجَمْعُ الْمُؤَنَّثِ السَّالِمُ</span><span class="rule-table-ru">ед. число, ломаное и правильное женское множественное</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُ وَالطُّلَّابُ وَالطَّالِبَاتُ.</span><span class="rule-table-ru">Пришли преподаватель, студенты и студентки.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْفَتْحَةُ عَلَامَةُ نَصْبٍ</span><span class="rule-table-ru">фатха — نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ وَجَمْعُ التَّكْسِيرِ</span><span class="rule-table-ru">ед. число и ломаное множественное</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ الْمُدَرِّسَ وَالطُّلَّابَ.</span><span class="rule-table-ru">Я увидел преподавателя и студентов.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْكَسْرَةُ عَلَامَةُ جَرٍّ</span><span class="rule-table-ru">касра — جَرٌّ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ، وَجَمْعُ التَّكْسِيرِ، وَجَمْعُ الْمُؤَنَّثِ السَّالِمُ</span><span class="rule-table-ru">ед. число, ломаное и правильное женское множественное</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى الْمُدَرِّسِ وَالطُّلَّابِ وَالطَّالِبَاتِ.</span><span class="rule-table-ru">Я поприветствовал преподавателя, студентов и студенток.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Второстепенные признаки</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَوْضِعُهَا</span><span class="rule-table-ru">где применяется</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْكَسْرَةُ عَلَامَةُ نَصْبٍ</span><span class="rule-table-ru">касра вместо фатхи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَمْعُ الْمُؤَنَّثِ السَّالِمُ</span><span class="rule-table-ru">правильное женское множественное</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَاتِ.</span><span class="rule-table-ru">Я увидел студенток.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْفَتْحَةُ عَلَامَةُ جَرٍّ</span><span class="rule-table-ru">фатха вместо касры</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-table-ru">имя, запрещённое от танвина</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى إِبْرَاهِيمَ وَعُثْمَانَ.</span><span class="rule-table-ru">Я поприветствовал Ибрахима и Усмана.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْوَاوُ عَلَامَةُ رَفْعٍ</span><span class="rule-table-ru">вау вместо даммы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَمْعُ الْمُذَكَّرِ السَّالِمُ وَالْأَسْمَاءُ الْخَمْسَةُ</span><span class="rule-table-ru">правильное мужское множественное и пять имён</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُونَ وَأَبُوكَ.</span><span class="rule-table-ru">Пришли преподаватели и твой отец.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْأَلِفُ عَلَامَةُ رَفْعٍ</span><span class="rule-table-ru">алиф вместо даммы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُثَنَّى</span><span class="rule-table-ru">двойственное число</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الطَّالِبَانِ.</span><span class="rule-table-ru">Пришли два студента.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْأَلِفُ عَلَامَةُ نَصْبٍ</span><span class="rule-table-ru">алиф вместо фатхи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَسْمَاءُ الْخَمْسَةُ</span><span class="rule-table-ru">пять имён</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ أَبَاكَ.</span><span class="rule-table-ru">Я увидел твоего отца.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْيَاءُ عَلَامَةُ نَصْبٍ</span><span class="rule-table-ru">йа вместо фатхи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُثَنَّى وَجَمْعُ الْمُذَكَّرِ السَّالِمُ</span><span class="rule-table-ru">двойственное и правильное мужское множественное</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَيْنِ وَالْمُدَرِّسِينَ.</span><span class="rule-table-ru">Я увидел двух студентов и преподавателей.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْيَاءُ عَلَامَةُ جَرٍّ</span><span class="rule-table-ru">йа вместо касры</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُثَنَّى، وَجَمْعُ الْمُذَكَّرِ السَّالِمِ، وَالْأَسْمَاءُ الْخَمْسَةُ</span><span class="rule-table-ru">три указанных типа имён</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى الطَّالِبَيْنِ وَالْمُدَرِّسِينَ وَأَبِيكَ.</span><span class="rule-table-ru">Я поприветствовал двух студентов, преподавателей и твоего отца.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три условия пяти имён</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَنْ تَكُونَ مُضَافَةً إِلَى غَيْرِ يَاءِ الْمُتَكَلِّمِ</span><span class="rule-term-ru">быть в идафе не с йа говорящего</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَنْ تَكُونَ مُفْرَدَةً</span><span class="rule-term-ru">быть в единственном числе</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَنْ تَكُونَ مُكَبَّرَةً</span><span class="rule-term-ru">не быть уменьшительной формой</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Когда условие не выполнено</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ أَبِي.</span><span class="rule-example-ru">Пришёл мой отец: رَفْعٌ с подразумеваемой даммой.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الْآبَاءُ وَالْإِخْوَانُ.</span><span class="rule-example-ru">Пришли отцы и братья: رَفْعٌ с явной даммой.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">هَذَا أُبَيٌّ وَأُخَيٌّ.</span><span class="rule-example-ru">Это «маленький отец» и «маленький брат»: уменьшительные формы получают обычные огласовки.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ الْأَبَوَانِ. رَأَيْتُ الْأَبَوَيْنِ.</span><span class="rule-example-ru">Пришли оба родителя; я увидел обоих родителей: формы изменяются как двойственное число.</span></div></div></div></div>', 3, 'rule', 'Таблица шарха связывает каждый основной и второстепенный признак с конкретными типами имён.', 'عَلَامَاتُ الْإِعْرَابِ الْأَصْلِيَّةُ فِي الْأَسْمَاءِ هِيَ الضَّمَّةُ لِلرَّفْعِ، وَالْفَتْحَةُ لِلنَّصْبِ، وَالْكَسْرَةُ لِلْجَرِّ. وَتَنُوبُ عَنْهَا عَلَامَاتٌ فَرْعِيَّةٌ بِحَسَبِ نَوْعِ الاِسْمِ.'),
('Мединский курс (Том 3)', '1', 'أَنْوَاعُ الْإِعْرَابِ وَأَقْسَامُهُ فِي الْأَسْمَاءِ (виды и способы выражения إِعْرَابٌ у имён)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْوَاعُ الْإِعْرَابِ: <span class="ar-tone-raf">الرَّفْعُ</span>، وَ<span class="ar-tone-nasb">النَّصْبُ</span>، وَ<span class="ar-tone-jarr">الْجَرُّ</span>. أَقْسَامُهُ: ظَاهِرٌ، وَمَحَلِّيٌّ، وَتَقْدِيرِيٌّ.</span><p class="rule-study-text">«Виды» показывают состояние имени. «Разделы» показывают, виден ли грамматический признак в произношении, определяется ли только синтаксическое место или признак подразумевается.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три способа выражения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقِسْمُ</span><span class="rule-table-ru">раздел</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ الظَّاهِرُ</span><span class="rule-table-ru">явный إِعْرَابٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَظْهَرُ فِيهِ عَلَامَةُ الْإِعْرَابِ</span><span class="rule-table-ru">признак виден</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ مُحَمَّدٌ. رَأَيْتُ مُحَمَّدًا. سَلَّمْتُ عَلَى مُحَمَّدٍ.</span><span class="rule-table-ru">Мухаммад пришёл; я увидел Мухаммада; я поприветствовал Мухаммада.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ الْمَحَلِّيُّ</span><span class="rule-table-ru">местный إِعْرَابٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَكُونُ تَأْثِيرُ الْإِعْرَابِ فِي الْمَحَلِّ لَا فِي اللَّفْظِ</span><span class="rule-table-ru">состояние относится к месту, не к форме</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">هَذَا طَالِبٌ.</span><span class="rule-table-ru">هَذَا — указательное имя в مَحَلٌّ رَفْعٌ как мубтада.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ التَّقْدِيرِيُّ</span><span class="rule-table-ru">подразумеваемый إِعْرَابٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَا تَظْهَرُ الْعَلَامَةُ لِسَبَبٍ مَانِعٍ وَتُقَدَّرُ</span><span class="rule-table-ru">признак скрыт по фонетической причине</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الْفَتَى.</span><span class="rule-table-ru">Юноша пришёл; дамма подразумевается на алифе.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Где встречается местный إِعْرَابٌ</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">هَذَا طَالِبٌ: هَذَا فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ.</span><span class="rule-example-ru">Это студент: указательное имя занимает место мубтада в رَفْعٌ.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ: الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ.</span><span class="rule-example-ru">«А поститься лучше для вас»: толкуемый масдар занимает место мубтада в رَفْعٌ.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">الطَّالِبُ يَكْتُبُ: الْجُمْلَةُ الْفِعْلِيَّةُ فِي مَحَلِّ رَفْعٍ خَبَرٌ.</span><span class="rule-example-ru">Студент пишет: глагольное предложение занимает место сказуемого в رَفْعٌ.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">الطَّالِبُ فِي الْفَصْلِ: شِبْهُ الْجُمْلَةِ فِي مَحَلِّ رَفْعٍ خَبَرٌ.</span><span class="rule-example-ru">Студент в аудитории: предложная группа занимает место сказуемого в رَفْعٌ.</span></div></div></div></div>', 4, 'rule', 'Шарх различает три состояния имени и три способа проявления грамматического окончания.', 'أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ ثَلَاثَةٌ: الرَّفْعُ، وَالنَّصْبُ، وَالْجَرُّ. وَأَقْسَامُهُ ثَلَاثَةٌ: إِعْرَابٌ ظَاهِرٌ، وَإِعْرَابٌ مَحَلِّيٌّ، وَإِعْرَابٌ تَقْدِيرِيٌّ.'),
('Мединский курс (Том 3)', '1', 'الْإِعْرَابُ التَّقْدِيرِيُّ فِي الْأَسْمَاءِ (подразумеваемый إِعْرَابٌ у имён)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">مَوَاضِعُ الْإِعْرَابِ التَّقْدِيرِيِّ: <span class="ar-tone-structure">الْمَقْصُورُ</span>، وَ<span class="ar-tone-structure">الْمَنْقُوصُ</span>، وَ<span class="ar-tone-structure">الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ</span>.</span><p class="rule-study-text">У каждой группы своя причина скрытия окончания: невозможность произнести огласовку на алифе, тяжесть огласовки на йа или занятость окончания касрой, подходящей к йа говорящего.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три группы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">тип</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا يُقَدَّرُ</span><span class="rule-table-ru">какие признаки скрыты</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السَّبَبُ</span><span class="rule-table-ru">причина</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ الْمَقْصُورُ</span><span class="rule-table-ru">имя на алиф</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ مُعْرَبٌ آخِرُهُ أَلِفٌ لَازِمَةٌ مَفْتُوحٌ مَا قَبْلَهَا</span><span class="rule-table-ru">изменяемое имя с обязательным алифом</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمَّةُ، وَالْفَتْحَةُ، وَالْكَسْرَةُ</span><span class="rule-table-ru">все три</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعَذُّرُ</span><span class="rule-table-ru">невозможность произнести огласовку</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ الْمَنْقُوصُ</span><span class="rule-table-ru">имя на йа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ مُعْرَبٌ آخِرُهُ يَاءٌ لَازِمَةٌ مَكْسُورٌ مَا قَبْلَهَا</span><span class="rule-table-ru">изменяемое имя с обязательной йа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمَّةُ وَالْكَسْرَةُ؛ وَتَظْهَرُ الْفَتْحَةُ</span><span class="rule-table-ru">дамма и касра; фатха видима</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الثِّقَلُ</span><span class="rule-table-ru">тяжесть произношения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ</span><span class="rule-table-ru">идафа к «моей» йа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَدِّي، بَلَدِي، زَمِيلِي، كِتَابِي</span><span class="rule-table-ru">мой дед, моя страна, мой товарищ, моя книга</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمَّةُ، وَالْفَتْحَةُ، وَالْكَسْرَةُ</span><span class="rule-table-ru">все три</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اشْتِغَالُ الْمَحَلِّ بِحَرَكَةِ الْمُنَاسَبَةِ</span><span class="rule-table-ru">место занято касрой, подходящей к йа</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полные примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ الْفَتَى: فَاعِلٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الْمُقَدَّرَةُ عَلَى الْأَلِفِ.</span><span class="rule-example-ru">Юноша пришёл: подлежащее в رَفْعٌ, дамма подразумевается.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ الْأَفْعَى: مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الْمُقَدَّرَةُ.</span><span class="rule-example-ru">Я увидел змею: прямое дополнение в نَصْبٌ, фатха подразумевается.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">ذَهَبْتُ إِلَى الْمُسْتَشْفَى: اسْمٌ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الْمُقَدَّرَةُ.</span><span class="rule-example-ru">Я пошёл в больницу: имя после предлога, касра подразумевается.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ الْقَاضِي. رَأَيْتُ الْمُحَامِيَ. ذَهَبْتُ إِلَى الْجَانِي.</span><span class="rule-example-ru">Пришёл судья; я увидел адвоката; я пошёл к преступнику. У الْمَنْقُوصُ фатха видима, а дамма и касра скрыты.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا قَاضٍ. سَلَّمْتُ عَلَى مُحَامٍ.</span><span class="rule-example-ru">Это судья; я поприветствовал адвоката. Йа удалена, а танвин заменяет удалённую йа.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ زَمِيلِي. رَأَيْتُ جَدِّي. سَلَّمْتُ عَلَى صَدِيقِي.</span><span class="rule-example-ru">Пришёл мой товарищ; я увидел моего деда; я поприветствовал моего друга. Все три окончания подразумеваются перед йа говорящего.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ مُحَامٍ. الْفَصْلُ خَالٍ.</span><span class="rule-example-ru">Пришёл адвокат; аудитория пуста. В رَفْعٌ неопределённого имени йа удалена.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">الْقَاضِي، قَاضِي مَكَّةَ، رَأَيْتُ قَاضِيًا.</span><span class="rule-example-ru">Йа сохраняется у имени с артиклем, у первого члена идафы и в состоянии نَصْبٌ: судья; судья Мекки; я увидел судью.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Когда удаляется йа имени الْمَنْقُوصُ</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَلَّا يَكُونَ مُحَلًّى بِأَلْ</span><span class="rule-term-ru">имя без определённого артикля</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَلَّا يَكُونَ مُضَافًا</span><span class="rule-term-ru">имя не является первым членом идафы</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَلَّا يَكُونَ مَنْصُوبًا</span><span class="rule-term-ru">имя не находится в نَصْبٌ</span></div></div></div></div>', 5, 'rule', 'Три группы имён получают подразумеваемые признаки по трём разным фонетическим причинам.', 'يَكُونُ الْإِعْرَابُ التَّقْدِيرِيُّ فِي الاِسْمِ الْمَقْصُورِ، وَالاِسْمِ الْمَنْقُوصِ، وَالْمُضَافِ إِلَى يَاءِ الْمُتَكَلِّمِ؛ فَتُقَدَّرُ الْعَلَامَةُ لِلتَّعَذُّرِ أَوِ الثِّقَلِ أَوِ اشْتِغَالِ الْمَحَلِّ.'),
('Мединский курс (Том 3)', '1', 'الْمَرْفُوعَاتُ مِنَ الْأَسْمَاءِ (имена в состоянии رَفْعٌ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَرْفُوعَاتُ مِنَ الْأَسْمَاءِ</span><p class="rule-study-text">Ниже сохранены все позиции и примеры таблицы шарха.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный перечень</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْضِعُ</span><span class="rule-table-ru">позиция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُبْتَدَأُ وَالْخَبَرُ</span><span class="rule-table-ru">мубтада и хабар</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّهُ غَفُورٌ.</span><span class="rule-table-ru">Аллах — Прощающий.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ كَانَ وَأَخَوَاتِهَا</span><span class="rule-table-ru">имя كَانَ и сестёр</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَكَانَ اللَّهُ غَفُورًا رَحِيمًا.</span><span class="rule-table-ru">Аллах был Прощающим, Милосердным.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ كَادَ وَأَخَوَاتِهَا</span><span class="rule-table-ru">имя كَادَ и сестёр</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَادَ الْكَافِرُ يُسْلِمُ.</span><span class="rule-table-ru">Неверующий едва не принял ислам.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ إِنَّ وَأَخَوَاتِهَا</span><span class="rule-table-ru">хабар إِنَّ и сестёр</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ.</span><span class="rule-table-ru">Поистине, Аллах знает сокровенное в сердцах.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ لَا النَّافِيَةِ لِلْجِنْسِ</span><span class="rule-table-ru">хабар полного отрицания</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَا مُؤْمِنَاتِ مُتَبَرِّجَاتٌ.</span><span class="rule-table-ru">Нет верующих женщин, выставляющих красоту напоказ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ</span><span class="rule-table-ru">исполнитель</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">خَلَقَنَا اللَّهُ.</span><span class="rule-table-ru">Аллах создал нас.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نَائِبُ الْفَاعِلِ</span><span class="rule-table-ru">заместитель исполнителя</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فُهِمَ الدَّرْسُ.</span><span class="rule-table-ru">Урок был понят.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْطُوفُ عَلَى الْمَرْفُوعِ</span><span class="rule-table-ru">сочинённое с رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ عَلِيٌّ وَسَعِيدٌ.</span><span class="rule-table-ru">Пришли Али и Саид.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَدَلُ مِنَ الْمَرْفُوعِ</span><span class="rule-table-ru">приложение к رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَجَحَ أَخُوكَ مُحَمَّدٌ.</span><span class="rule-table-ru">Твой брат Мухаммад преуспел.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَعْتُ الْمَرْفُوعِ</span><span class="rule-table-ru">определение к رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا رَجُلٌ صَالِحٌ.</span><span class="rule-table-ru">Это праведный мужчина.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَوْكِيدُ الْمَرْفُوعِ</span><span class="rule-table-ru">усиление слова в رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ الْمُدِيرُ نَفْسُهُ.</span><span class="rule-table-ru">Пришёл сам директор.</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'Полная таблица именных позиций, которые шарх относит к состоянию رَفْعٌ.', 'الْمَرْفُوعَاتُ مِنَ الْأَسْمَاءِ هِيَ الْمُبْتَدَأُ وَالْخَبَرُ، وَاسْمُ كَانَ وَكَادَ وَأَخَوَاتِهِمَا، وَخَبَرُ إِنَّ وَأَخَوَاتِهَا وَلَا النَّافِيَةِ لِلْجِنْسِ، وَالْفَاعِلُ وَنَائِبُهُ، وَالتَّوَابِعُ لِلْمَرْفُوعِ.'),
('Мединский курс (Том 3)', '1', 'الْمَجْرُورَاتُ مِنَ الْأَسْمَاءِ (имена в состоянии جَرٌّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَجْرُورَاتُ مِنَ الْأَسْمَاءِ</span><p class="rule-study-text">Состояние جَرٌّ возникает после предлога, во втором члене идафы и у зависимого слова, согласованного с уже مَجْرُورٌ именем.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный перечень</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْضِعُ</span><span class="rule-table-ru">позиция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْمَسْبُوقُ بِحَرْفِ جَرٍّ</span><span class="rule-table-ru">имя после предлога</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الطُّلَّابُ فِي الْفَصْلِ.</span><span class="rule-table-ru">Студенты находятся в аудитории.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْمُضَافُ إِلَيْهِ</span><span class="rule-table-ru">второй член идафы</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْقُرْآنُ كِتَابُ اللَّهِ.</span><span class="rule-table-ru">Коран — Книга Аллаха.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْمَعْطُوفُ عَلَى الْمَجْرُورِ</span><span class="rule-table-ru">сочинённое с جَرٌّ</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى خَالِدٍ وَسَعِيدٍ.</span><span class="rule-table-ru">Я поприветствовал Халида и Саида.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْبَدَلُ مِنَ الْمَجْرُورِ</span><span class="rule-table-ru">приложение к جَرٌّ</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">ذَهَبْتُ إِلَى أَخِيكَ مُحَمَّدٍ.</span><span class="rule-table-ru">Я пошёл к твоему брату Мухаммаду.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">نَعْتُ الْمَجْرُورِ</span><span class="rule-table-ru">определение к جَرٌّ</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَافَرْتُ مَعَ رَجُلٍ عَالِمٍ.</span><span class="rule-table-ru">Я путешествовал с учёным мужчиной.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">تَوْكِيدُ الْمَجْرُورِ</span><span class="rule-table-ru">усиление слова в جَرٌّ</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى الْمُدِيرِ نَفْسِهِ.</span><span class="rule-table-ru">Я поприветствовал самого директора.</span></td></tr></tbody></table></div></div></div>', 7, 'rule', 'Шарх перечисляет имя после предлога, второй член идафы и четыре зависимые позиции.', 'الْمَجْرُورَاتُ مِنَ الْأَسْمَاءِ هِيَ الاِسْمُ الْمَسْبُوقُ بِحَرْفِ جَرٍّ، وَالْمُضَافُ إِلَيْهِ، وَالتَّوَابِعُ لِلْمَجْرُورِ.'),
('Мединский курс (Том 3)', '1', 'الْمَنْصُوبَاتُ مِنَ الْأَسْمَاءِ (имена в состоянии نَصْبٌ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَنْصُوبَاتُ مِنَ الْأَسْمَاءِ</span><p class="rule-study-text">В таблице сохранены все позиции, названные шархом: управляемые имена и сказуемые, пять видов дополнения, حَالٌ, تَمْيِيزٌ, исключение, обращение и зависимые слова.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный перечень</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْضِعُ</span><span class="rule-table-ru">позиция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اسْمُ إِنَّ وَأَخَوَاتِهَا</span><span class="rule-table-ru">имя إِنَّ и сестёр</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">إِنَّ اللَّهَ غَفُورٌ.</span><span class="rule-table-ru">Поистине, Аллах — Прощающий.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ كَانَ وَأَخَوَاتِهَا</span><span class="rule-table-ru">хабар كَانَ и сестёр</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كَانَ الطَّعَامُ لَذِيذًا.</span><span class="rule-table-ru">Еда была вкусной.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ كَادَ وَأَخَوَاتِهَا</span><span class="rule-table-ru">хабар كَادَ и сестёр</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَادَ الْكَافِرُ يُسْلِمُ.</span><span class="rule-table-ru">Неверующий едва не принял ислам; глагольное предложение занимает مَحَلٌّ نَصْبٌ как хабар.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اسْمُ لَا النَّافِيَةِ لِلْجِنْسِ</span><span class="rule-table-ru">имя полного отрицания</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">لَا طَالِبَ عِلْمٍ كَسْلَانُ.</span><span class="rule-table-ru">Ни один ищущий знание не ленив.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فَهِمْتُ الدَّرْسَ.</span><span class="rule-table-ru">Я понял урок.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ فِيهِ</span><span class="rule-table-ru">обстоятельство времени/места</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سَافَرْتُ لَيْلًا. جَلَسْتُ عِنْدَ الْمُدِيرِ.</span><span class="rule-table-ru">Я путешествовал ночью; я сидел у директора.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ لِأَجْلِهِ</span><span class="rule-table-ru">дополнение причины</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جِئْتُ رَغْبَةً فِي الْعِلْمِ.</span><span class="rule-table-ru">Я пришёл из стремления к знанию.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ مَعَهُ</span><span class="rule-table-ru">совместное дополнение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">سِرْتُ وَالْجَبَلَ.</span><span class="rule-table-ru">Я шёл вдоль горы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ الْمُطْلَقُ</span><span class="rule-table-ru">абсолютное дополнение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَفِظْتُ الدَّرْسَ حِفْظًا.</span><span class="rule-table-ru">Я выучил урок полным заучиванием.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-table-ru">обстоятельство состояния</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جِئْتُ مُسْرِعًا.</span><span class="rule-table-ru">Я пришёл спеша.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">التَّمْيِيزُ</span><span class="rule-table-ru">поясняющее имя</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">عِنْدِي صَاعٌ تَمْرًا. أَنَا أَكْبَرُ مِنْكَ سِنًّا.</span><span class="rule-table-ru">У меня са‘ фиников; я старше тебя по возрасту.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمُسْتَثْنَى</span><span class="rule-table-ru">исключаемое имя</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَضَرَ الطُّلَّابُ إِلَّا حَامِدًا.</span><span class="rule-table-ru">Студенты пришли, кроме Хамида.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمُنَادَى</span><span class="rule-table-ru">обращение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَا عَبْدَ اللَّهِ. يَا رَجُلًا سَاعِدْنِي.</span><span class="rule-table-ru">О Абдуллах! О мужчина, помоги мне!</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَعْطُوفُ عَلَى الْمَنْصُوبِ</span><span class="rule-table-ru">сочинённое с نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ عَلِيًّا وَسَعِيدًا.</span><span class="rule-table-ru">Я увидел Али и Саида.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْبَدَلُ مِنَ الْمَنْصُوبِ</span><span class="rule-table-ru">приложение к نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">نَصَحْتُ أَخَاكَ مُحَمَّدًا.</span><span class="rule-table-ru">Я наставил твоего брата Мухаммада.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">نَعْتُ الْمَنْصُوبِ</span><span class="rule-table-ru">определение к نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ رَجُلًا صَالِحًا.</span><span class="rule-table-ru">Я увидел праведного мужчину.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَوْكِيدُ الْمَنْصُوبِ</span><span class="rule-table-ru">усиление слова в نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ الْمُدِيرَ نَفْسَهُ.</span><span class="rule-table-ru">Я увидел самого директора.</span></td></tr></tbody></table></div></div></div>', 8, 'rule', 'Полный список именных позиций в نَصْبٌ с примерами шарха.', 'تَدْخُلُ فِي الْمَنْصُوبَاتِ أَسْمَاءُ النَّوَاسِخِ وَأَخْبَارُهَا الْمَنْصُوبَةُ، وَالْمَفَاعِيلُ، وَالْحَالُ، وَالتَّمْيِيزُ، وَالْمُسْتَثْنَى، وَالْمُنَادَى، وَالتَّوَابِعُ لِلْمَنْصُوبِ.'),
('Мединский курс (Том 3)', '1', 'التَّوَابِعُ (зависимые слова)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">التَّوَابِعُ: <span class="ar-tone-structure">النَّعْتُ</span>، وَ<span class="ar-tone-structure">التَّوْكِيدُ</span>، وَ<span class="ar-tone-structure">الْعَطْفُ</span>، وَ<span class="ar-tone-structure">الْبَدَلُ</span>.</span><p class="rule-study-text">Зависимое слово разделяет с предыдущим его إِعْرَابٌ. Для определения шарх также называет согласование в роде, определённости и числе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре вида</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَاعِدَةُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّعْتُ</span><span class="rule-table-ru">определение</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَابِعٌ لِلْمَنْعُوتِ فِي جَمِيعِ أَحْوَالِهِ</span><span class="rule-table-ru">следует определяемому</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرَّجُلُ الصَّالِحُ مَحْبُوبٌ. رَأَيْتُ عَالِمَيْنِ كَبِيرَيْنِ. مَرَرْتُ بِنِسَاءٍ صَالِحَاتٍ. أَيْنَ الطُّلَّابُ الْجُدُدُ؟</span><span class="rule-table-ru">Праведный мужчина любим; я увидел двух великих учёных; я прошёл мимо праведных женщин; где новые студенты?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّوْكِيدُ</span><span class="rule-table-ru">усиление</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَابِعٌ لِلْمُؤَكَّدِ وَلَا يَأْتِي الْمَعْنَوِيُّ إِلَّا مَعْرِفَةً</span><span class="rule-table-ru">следует усиливаемому; смысловое усиление определённо</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَضَرَ الطُّلَّابُ كُلُّهُمْ. سَأَلْتُ الْمُدِيرَ نَفْسَهُ. جَاءَ الطَّالِبَانِ كِلَاهُمَا.</span><span class="rule-table-ru">Пришли все студенты; я спросил самого директора; пришли оба студента.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَطْفُ</span><span class="rule-table-ru">сочинение</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَابِعٌ لِلْمَعْطُوفِ عَلَيْهِ فِي إِعْرَابِهِ</span><span class="rule-table-ru">следует слову перед союзом</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَ عَلِيٌّ وَسَعِيدٌ. ذَهَبْتُ إِلَى الرِّيَاضِ ثُمَّ الْمَدِينَةِ. أَعَلِيٌّ فِي الدَّارِ أَمْ خَالِدٌ؟</span><span class="rule-table-ru">Пришли Али и Саид; я поехал в Эр-Рияд, затем в Медину; Али в доме или Халид?</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَدَلُ</span><span class="rule-table-ru">приложение/замена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَابِعٌ لِلْمُبْدَلِ مِنْهُ وَلَا يُشْتَرَطُ تَوَافُقُهُمَا فِي التَّعْرِيفِ وَالتَّنْكِيرِ</span><span class="rule-table-ru">следует по إِعْرَابٌ, но не обязательно по определённости</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَجَحَ أَخُوكَ هَاشِمٌ. أَعْرِفُ أَخَاكَ هَاشِمًا. اقْتَدِ بِالْفَارُوقِ عُمَرَ.</span><span class="rule-table-ru">Твой брат Хашим преуспел; я знаю твоего брата Хашима; следуй за аль-Фаруком Умаром.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Дополнительные примеры всех четырёх видов</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">نَجَحَ الطُّلَّابُ الْآتِيَةُ أَسْمَاؤُهُمْ.</span><span class="rule-example-ru">Студенты, имена которых следуют далее, преуспели.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">سَأَلْتُ الطُّلَّابَ كُلَّهُمْ. مَرَرْتُ بِالرَّجُلِ عَيْنِهِ.</span><span class="rule-example-ru">Я спросил всех студентов; я прошёл мимо самого этого мужчины.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">سَلَّمْتُ عَلَى الْمُدِيرِ نَفْسِهِ. سَلَّمْتُ عَلَى الطُّلَّابِ كُلِّهِمْ.</span><span class="rule-example-ru">Я поприветствовал самого директора; я поприветствовал всех студентов.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَتَيْنِ كِلْتَيْهِمَا.</span><span class="rule-example-ru">Я увидел обеих студенток.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">اللَّهَ اللَّهَ فِي أَصْحَابِي.</span><span class="rule-example-ru">Бойтесь Аллаха в отношении моих сподвижников.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">رَأَيْتُ عَلِيًّا فَسَعِيدًا. تَزَوَّجْ فَاطِمَةَ أَوْ خَدِيجَةَ.</span><span class="rule-example-ru">Я увидел Али, затем Саида; женись на Фатиме или Хадидже.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">رَأَيْتُ وَالِدَيْهِ أُمَّهُ وَأَبَاهُ.</span><span class="rule-example-ru">Я увидел его родителей — его мать и отца.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">هَؤُلَاءِ الطُّلَّابُ مُجْتَهِدُونَ. هَؤُلَاءِ الطَّالِبَاتُ مُجْتَهِدَاتٌ.</span><span class="rule-example-ru">Эти студенты усердны; эти студентки усердны.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Виды определения</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">نَعْتٌ حَقِيقِيٌّ</span><span class="rule-term-ru">обычное определение самого имени</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">نَعْتٌ سَبَبِيٌّ</span><span class="rule-term-ru">определение связанного с именем свойства: جَاءَ مُحَمَّدٌ الْحَسَنُ خُلُقُهُ — пришёл Мухаммад, чей нрав прекрасен</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Виды усиления</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">تَوْكِيدٌ مَعْنَوِيٌّ</span><span class="rule-term-ru">смысловое: النَّفْسُ، الْعَيْنُ، كُلٌّ، أَجْمَعُ، جَمِيعٌ، كِلَا، كِلْتَا</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">تَوْكِيدٌ لَفْظِيٌّ</span><span class="rule-term-ru">словесное повторение: جَاءَ جَاءَ عَلِيٌّ؛ لَنْ لَنْ أُهْمِلَ دُرُوسِي — Али пришёл; я никогда не заброшу уроки</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Виды сочинения</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">عَطْفُ النَّسَقِ</span><span class="rule-term-ru">сочинение посредством союза</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">عَطْفُ الْبَيَانِ</span><span class="rule-term-ru">поясняющее сочинение, похожее на بَدَلٌ: أَقْسَمَ بِاللَّهِ أَبُو حَفْصٍ عُمَرُ — поклялся Аллахом Абу Хафс Умар</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре вида بَدَلٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ كُلٍّ مِنْ كُلٍّ</span><span class="rule-table-ru">полная замена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَجَحَ أَخُوكَ هَاشِمٌ.</span><span class="rule-table-ru">Твой брат Хашим преуспел.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ بَعْضٍ مِنْ كُلٍّ</span><span class="rule-table-ru">часть от целого</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَكَلْتُ الدَّجَاجَةَ نِصْفَهَا.</span><span class="rule-table-ru">Я съел половину курицы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ اشْتِمَالٍ</span><span class="rule-table-ru">замена по охватываемому свойству</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَفَعَنِي الْمُعَلِّمُ عِلْمُهُ.</span><span class="rule-table-ru">Мне принесло пользу знание учителя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ غَلَطٍ</span><span class="rule-table-ru">исправление оговорки</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَكَلْتُ خُبْزًا تَمْرًا.</span><span class="rule-table-ru">Я ел хлеб — то есть финики.</span></td></tr></tbody></table></div></div></div>', 9, 'rule', 'Определение, усиление, сочинение и приложение следуют за главным словом по إِعْرَابٌ; шарх объясняет виды каждого.', 'التَّوَابِعُ أَرْبَعَةٌ: النَّعْتُ، وَالتَّوْكِيدُ، وَالْعَطْفُ، وَالْبَدَلُ. وَالتَّابِعُ يُشَارِكُ مَا قَبْلَهُ فِي إِعْرَابِهِ، وَفِي الْخَصَائِصِ الَّتِي بَيَّنَهَا الشَّارِحُ.'),
('Мединский курс (Том 3)', '1', 'الْمُعْرَبُ وَالْمَبْنِيُّ مِنَ الْأَفْعَالِ وَعَلَامَاتُهُ (изменяемые и неизменяемые глаголы и их признаки)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَاضِي وَالْأَمْرُ مَبْنِيَّانِ، وَالْمُضَارِعُ مُعْرَبٌ أَوْ مَبْنِيٌّ.</span><p class="rule-study-text">Настояще-будущий глагол становится неизменяемым только в двух названных случаях; во всех остальных он изменяется по состояниям رَفْعٌ، نَصْبٌ и جَزْمٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Когда الْمُضَارِعُ неизменяем</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السَّبَبُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبِنَاءُ</span><span class="rule-table-ru">на чём построен</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">اتِّصَالُ نُونِ التَّوْكِيدِ اتِّصَالًا مُبَاشِرًا</span><span class="rule-table-ru">прямое присоединение усилительной нун</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَاللَّهِ لَأَقْرَأَنَّ.</span><span class="rule-table-ru">Клянусь Аллахом, я непременно прочитаю.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى الْفَتْحِ</span><span class="rule-table-ru">построен на фатхе</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اتِّصَالُ نُونِ النِّسْوَةِ</span><span class="rule-table-ru">присоединение нун женского множественного</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الطَّالِبَاتُ يَجْتَهِدْنَ.</span><span class="rule-table-ru">Студентки усердствуют.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى السُّكُونِ</span><span class="rule-table-ru">построен на сукуне</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Изменяемый الْمُضَارِعُ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَذْهَبُ. لَمْ أَذْهَبْ. لَنْ أَذْهَبَ.</span><span class="rule-example-ru">Я иду; я не пошёл; я не пойду. Формы показывают رَفْعٌ, جَزْمٌ и نَصْبٌ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Основные признаки الْمُضَارِعُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">какая форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الضَّمَّةُ عَلَامَةُ رَفْعٍ</span><span class="rule-table-ru">дамма — رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَارِعٌ لَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ</span><span class="rule-table-ru">к концу ничего не присоединено</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَذْهَبُ، تَذْهَبُ، يَذْهَبُ، نَذْهَبُ</span><span class="rule-table-ru">я, ты, он, мы идём</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْفَتْحَةُ عَلَامَةُ نَصْبٍ</span><span class="rule-table-ru">фатха — نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَارِعٌ لَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ</span><span class="rule-table-ru">к концу ничего не присоединено</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أُرِيدُ أَنْ أَذْهَبَ. لَنْ أَذْهَبَ. جِئْتُ كَيْ أَتَعَلَّمَ.</span><span class="rule-table-ru">Хочу пойти; не пойду; пришёл, чтобы учиться.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">السُّكُونُ عَلَامَةُ جَزْمٍ</span><span class="rule-table-ru">сукун — جَزْمٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَارِعٌ لَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ</span><span class="rule-table-ru">к концу ничего не присоединено</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ أَذْهَبْ. لَا تَذْهَبْ. لَمَّا أَذْهَبْ.</span><span class="rule-table-ru">Я не пошёл; не уходи; я ещё не пошёл.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Второстепенные признаки الْمُضَارِعُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَوْضِعُهَا</span><span class="rule-table-ru">где применяется</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ثُبُوتُ النُّونِ عَلَامَةُ رَفْعٍ</span><span class="rule-table-ru">сохранение нун — رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><span class="rule-table-ru">пять форм</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَذْهَبُونَ، تَذْهَبُونَ، يَذْهَبَانِ، تَذْهَبَانِ، تَذْهَبِينَ</span><span class="rule-table-ru">они идут; вы идёте; они двое идут; вы двое идёте; ты, женщина, идёшь</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَذْفُ النُّونِ عَلَامَةُ نَصْبٍ وَجَزْمٍ</span><span class="rule-table-ru">удаление нун — نَصْبٌ или جَزْمٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><span class="rule-table-ru">пять форм</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَنْ يَذْهَبُوا. لَمْ يَذْهَبُوا. لَنْ يَذْهَبَا. لَمْ تَذْهَبِي.</span><span class="rule-table-ru">Они не пойдут; они не пошли; двое не пойдут; ты не пошла.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">حَذْفُ حَرْفِ الْعِلَّةِ عَلَامَةُ جَزْمٍ</span><span class="rule-table-ru">удаление слабой буквы — جَزْمٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ الْمُعْتَلُّ النَّاقِصُ</span><span class="rule-table-ru">конечно-слабый глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ يَمْشِ. لَا تَرْمِ. لَمَّا أَنْسَ.</span><span class="rule-table-ru">Он не шёл; не бросай; я ещё не забыл.</span></td></tr></tbody></table></div></div></div>', 10, 'rule', 'Прошедший и повелительный глаголы всегда неизменяемы; الْمُضَارِعُ строится или изменяется по условиям шарха.', 'الْفِعْلُ الْمَاضِي وَفِعْلُ الْأَمْرِ مَبْنِيَّانِ دَائِمًا. وَالْفِعْلُ الْمُضَارِعُ يُبْنَى مَعَ نُونِ التَّوْكِيدِ الْمُبَاشِرَةِ أَوْ نُونِ النِّسْوَةِ، وَيُعْرَبُ فِيمَا عَدَا ذَلِكَ بِالرَّفْعِ أَوِ النَّصْبِ أَوِ الْجَزْمِ.'),
('Мединский курс (Том 3)', '1', 'الْإِعْرَابُ التَّقْدِيرِيُّ فِي الْأَفْعَالِ (подразумеваемый إِعْرَابٌ у глаголов)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">مَوَاضِعُ الْإِعْرَابِ التَّقْدِيرِيِّ فِي الْفِعْلِ الْمُضَارِعِ</span><p class="rule-study-text">Подразумеваемый признак встречается при слабой конечной букве или при слиянии одинаковых согласных.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три случая</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак и причина</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْمُعْتَلُّ النَّاقِصُ فِي الرَّفْعِ</span><span class="rule-table-ru">конечно-слабый в رَفْعٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمَّةٌ مُقَدَّرَةٌ لِلثِّقَلِ فِي الْيَاءِ وَالْوَاوِ، وَلِلتَّعَذُّرِ فِي الْأَلِفِ</span><span class="rule-table-ru">дамма скрыта из-за тяжести или невозможности</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَمْشِي، يَدْعُو، يَنْسَى</span><span class="rule-table-ru">он идёт; призывает; забывает</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمُعْتَلُّ بِالْأَلِفِ فِي النَّصْبِ</span><span class="rule-table-ru">глагол на алиф в نَصْبٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَتْحَةٌ مُقَدَّرَةٌ لِلتَّعَذُّرِ</span><span class="rule-table-ru">фатха скрыта из-за невозможности</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَنْ أَنْسَى.</span><span class="rule-table-ru">Я не забуду.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">الْمُضَعَّفُ فِي الْجَزْمِ</span><span class="rule-table-ru">удвоенный глагол в جَزْمٌ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سُكُونٌ مُقَدَّرٌ لِالْتِقَاءِ السَّاكِنَيْنِ</span><span class="rule-table-ru">сукун скрыт из-за встречи двух сукунов</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ أَحُجَّ؛ وَالْأَصْلُ: لَمْ أَحْجُجْ.</span><span class="rule-table-ru">Я не совершил хадж; исходная форма показывает два согласных.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Где фатха видима</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">لَنْ أَدْعُوَ. لَنْ أَمْشِيَ.</span><span class="rule-example-ru">У глаголов на вау или йа фатха в نَصْبٌ произносится явно.</span></div></div></div></div>', 11, 'rule', 'Шарх называет три случая подразумеваемого признака у الْمُضَارِعُ и объясняет причину каждого.', 'تُقَدَّرُ الضَّمَّةُ فِي رَفْعِ الْمُضَارِعِ الْمُعْتَلِّ النَّاقِصِ، وَتُقَدَّرُ الْفَتْحَةُ فِي نَصْبِ الْمُعْتَلِّ بِالْأَلِفِ، وَيُقَدَّرُ السُّكُونُ فِي جَزْمِ الْمُضَارِعِ الْمُضَعَّفِ لِالْتِقَاءِ السَّاكِنَيْنِ.');

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'الإِعْرَابُ وَالْبِنَـاءُ
( أ ) في الأسماءِ :
الاسمُ إِمَّا مُعْرَبٌ وإِما مَبْنِيٌّ .
فالْمُعْرَبُ ، هو : ما تَغَيَّرَ آخِرُهُ بسبب العامل ، نحو :
جاءَ الْمُدَرِّسُ . المدرسُ : فاعل مرفوع وعلامة رفعه الضَّمَّة .
سألت المدرسَ . المدرسَ : مفعول به منصوب وعلامة نصبه الفتحة .
سلّمت على المدرسِ . المدرسِ : اسم مجرور وعَلامة جرَّه الكسرة .
فالتَّغَيُّرُ الذي حَدَثَ في آخر كلمة ( المدرس ) الضمة ، ثم الفتحة ، ثم الكسرة ، هذا التَّغَيُّرُ يدلّ على أن كلمة المدرس مُعْرَبَة ؛ لأن آخرها تغيَّر بسبب العامل ، وهو الفعل وحرف الجر.
والْمَبْنِيُّ ، هو : ما لا يَتَغَيَّرُ آخرُه بسببِ العَامِلِ ، أي : يَلْزَمُ حالةً واحدةً ، نحو :
جاء هؤلاءِ . هؤلاءِ : في محل رفع فاعل مبنيّ على الكسر .
رأيت هؤلاءِ . هؤلاءِ : في محل نصب مفعول به مبنيّ على الكسر .
سلّمت على هؤلاءِ . هؤلاءِ : في محل جر مبنيّ على الكسر .
فكلمة هؤلاء كما ترى لم يتَغيَّر آخرها مع أنّ العاملَ قد تغيَّر ، فهي إذا كلمة مَبْنِيَّة ؛ لأنَّ آخرها لم يتغيَّر مع تغيُّر العامل .
* نَلْحَظُ مِمَّا سَبَقَ : أنّ الاسم المعرب، نقول في إعرابه: مرفوع ، أو منصوب، أو مجرور.
أَمَّا الاسمُ المبنيّ ، فنقول في إعرابه : في محل رفع ، أو في محل نصب ، أو في محل جرّ .', 3, 3, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '1' and sort_order = 1;

