insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'أَنْوَاعُ الإِْعْرَابِ
أنواع الإعراب في الأسماء ثلاثة : الرَّفْعُ ، والنَّصْبُ ، والْجَرُّ .
أَقْسَامُ الإِعْرابِ
أقسام الإعراب في الأسماء ثلاثة : الإعراب الظَّاهر ، والإعراب التَّقْدِيري ، والإعراب الْمَحَلّي .
1- الإعرابُ الظَّاهِرُ : هو : الإعراب الذي تظهر فيه علامات الإعراب، نحو :
جاء محمدٌ .              رأيت محمداً               سلّمت على محمدٍ .
2- الإعرابُ الْمَحَلِّيُّ: هو الإعراب الذي لا تظهر فيه العلامات، ولا تُقَدَّر، ويكون تأثير
الإعراب في الْمَحَلَّ لا في اللفظ .
* الإعراب المحلَّي يكون في الأسماء المبنيّة ، وفي الْجُمَل ، وفي شبه الجملة ، وفي المصـدر
الْمُؤَوَّل .
الأمثلة : هذا طالبٌ : اسم الإشارة مبتدأ في محل رفع .
" و أن تصوموا خيرٌ لكم " : المصدر المؤوَّل في مَحَلٌّ رَفْعٌ مبتدأ .
الطالبُ يكتبُ : الجملة الفعلية في محل رفع خبر .
الطالبُ في الفصلِ : شبه الجملة في محل رفع خبر .', 8, 9, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '1' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', '3- الإعرابُ التَّقْدِيرِيُّ ، هو : الإعراب الذي لا تظهر فيه علامة الإعراب لسببٍ مانع
وتُقَدَّر العلامة كأنها مذكورة . والأسماء التي تُعرب إعراباً تقديريا ثلاثة أنواع، هي :
( أ ) الاسمُ الْمَقْصُورُ : هو الاسم المعرب الذي آخره ألفُ لازمة مفتوح ما قبلها .
تُقَدَّر فيه العلامات الثَّلاثُ ، نحو :
جاء الفَتَى : فاعل مرفوع وعلامة رفعه الضمة المقدّرة على الألف .
رأيت الأَفْعَى : مفعول به منصوب وعلامة نصبه الفتحة المقدّرة على الألف .
ذهبت إلى المستشفَى : اسم مجرور بـ ( إلى ) وعلامة جرَّه الكسرة المقدّرة على
الألف .
وسبب منع ظهور العلامة ، هو : التَعَذُّرُ ، أي : لا يُمكن أن تظهر العلامة على
الألف أبداً .
(ب) الاسم الْمَنْقُوصُ : هو الاسم المعرب الذي آخره ياء لازمة مكسور ما قبلها .
تقدَّرُ فيه الضمة والكسرة ، وتَظْهَرُ الفتحة ، نحو :
جاء القاضِي : فاعل مرفوع وعلامة رفعه الضمة المقدَّرة على الياء .
رأيت المحاميَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة .
ذهبت إلى الجانِي : اسم مجرور بـ ( إلى ) وعلامة جرَّهِ الكسرة المقدّرة على الياء .
وسبب منع ظهور العلامة ، هو : الثَِّقَل، أي : يُمكن أن تظهر العلامة على الياء
ولكنها ثقيلة في النُّطق .
*   قد يكون المنقوص محذوف الياء ، وتُحْذَف الياء في ثلاث حالات ، هي :
1- إذا لم يكن مُحَلًّى بالألف واللاَّم ، نحو : هذا قاضٍ: خبر مرفوع وعلامة رفعه الضمة
المقدّرة على الياء المحذوفة . والتنوين عِوَضٌ عن الياء المحذوفة .
ونحو : سلّمت على مُحَامٍ : اسم مجرور بـ (على) وعلامة جرَّه الكسرة المقدّرة على
الياء المحذوفة .
2- إذا لم يكن مُضَافاً ، نحو : هذا قاضٍ . جاء مُحَامٍ . الفصلُ خَالٍ .
3- إذا لم يكن منصوباً ، كالأمثلة السابقة .
أمَّا إذا كان مُحَلًّى بأل ، نحو : القاضي ، أو كان مضافاً ، نحو : قاضِي مكةَ ، أو كان
منصوباً ، نحو : رأيت قاضياً ، فَإِنَّ الياء تَثْبُتُ وتَظْهر كما ترى في الأمثلة .
( ج ) الْمُضَافُ إلى ياءِ الْمُتَكَلَّمِ ، نحو : جَدَّي ، بَلَدِي ، زَمِيلي ، كِتَابِي .
تُقدَّر فيه العلاماتُ الثلاثُ :
جاءَ زميلِي : فاعل مرفوع وعلامة رفعه الضمة المقدّرة على ما قبل ياء المتكلَّم ، وهو
مضاف ، وياء المتكلَّم في محل جرّ مضاف إليه .
رأيت جدَّي : مفعول به منصوب وعلامة نصبه الفتحة المقدّرة على ما قبل ياء المتكلّم ،
وهو مضاف ، وياء المتكلَّم في محل جرّ مضاف إليه .
سلَّمت على صديقِي : اسم مجرور بـ ( على ) وعلامة جرَّه الكسرة المقدّرة على ما قبل
ياء المتكلَّم ، وهو مضاف ، وياء المتكلَّم في محل جرّ مضاف إليه .
سبب منع ظهور العلامة ، هو : اشْتِغَال الْمَحَلَّ لِلْمُنَاسَبَةِ ، أي : أنّ آخر الكلمة مَشْغُول بالكسرة التي تُنَاسِب ياء المتكلم .', 9, 11, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '1' and sort_order = 5;

