insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'التَّوَابِعُ
التَّابِعُ ، هو : الاسمُ الْمُشَارِكُ لِمَا قبلَه في إِعْرَابِهِ ، وَتَذْكِيرهِ وَتَأْنِيثِهِ ، وَتَنْكِيرِهِ وَتَعْرِيفِهِ ،
وَإِفْرادِهِ وَتَثْنِيَتِهِ وَجَمْعِهِ .
وهو أربعة أنواع ، هي : النَّعْتُ ، والتَّوْكِيدُ ، والْعَطْفُ ، والْبَدَلُ .
أولا : النَّعْتُ :
النَّعْتُ : تَاِبعٌ لِلْمَنْعُوتِ في جميع أحواله .
الأمثلة :
الرجلُ الصَّالِحُ مَحبوبٌ  .                     رأيت عَالِمَيْنِ كَبِيرَيْنِ .
مَرَرْتُ بِنِسَاءٍ صَالحاتٍ .                       أينَ الطُّلاَّبُ الْجُدُدُ ؟
والنعت نوعان :
1- نعتٌ حَقِيقِيٌّ ، كما في الأمثلة السابقة .
2- نعتٌ سَبَبِيٌّ ، نحو : جاء محمدٌ الْحَسَنُ خُلُقُه . نجح الطلابُ الآتيةُ أسماؤُهم .
ثانيا : التَّوْكِيدُ :
التَّوكيدُ : تابعٌ لِلْمُؤَكَّدِ في جميع أحواله غير أنَّه لا يأتي إلاَّ معرفةً .
الأمثلة :
حضرَ الطُّلابُ كُلُّهم .                   سألتُ الطُّلابَ كُلَّهم .
سألتُ المديرَ نفسَه .                     مررت بالرجلِ عَيْنِهِ .
سلَّمت على المديرِ نفسِهِ .               سلّمت على الطلابِ كلِّهِم .
جاء الطالبانِ كلاهما .                   رأيت الطالبتينِ كلتيهما .
والتوكيد نوعان :
1- مَعْنَوِيٌّ ، ويكون بألفاظ معلومة، هي : النَّفْسُ ، والعَيْنُ ، وكُلّ ، وأَجْمَع ، وجَمِيع
وكِلاَ ، وكِلْتا. ( وهذا التوكيد هو الذي لا يأتي إلاَّ معرفة )
2- لَفْظِيٌّ ، ويكون بِتَكْرَار اللَّفْظِ نفسِه ، نحو : جاء جاء عليٌّ .
" اللهَ اللهَ في أصحابي " .                 لَنْ لَنْ أُهمَل دروسي .
ثالثا : العَطْفُ :
العطفُ : تاِبعٌ لِلْمَعْطُوفِ في جميع أحواله .
الأمثلة :
جاء عليٌ وسعيدٌ .                        رأيت عليّاً فسعيداً .
ذهبت إلى الرياضِ ثم المدينةِ .             تَزَوَّجْ فاطمةَ أو خديجةَ .
أعليٌّ في الدارِ أم خالدٌ ؟
العطف نوعان :
1- عطفُ النَّسَقِ ، وهو المعطوف بالحرف ، كالأمثلة السابقة .
2- عطفُ البَيَانِ ، وهو يُشْبِهُ البدل ، نحو : أَقْسَمَ باللهِ أبو حَفْصٍ عمرُ .
رابعاً : الْبَدَلُ :
البدل:تابعٌ لِلْمُبْدَلِ منه في جميع أحواله غير أنّه لا يُشْتَرَطُ أَنْ يَتْبَعَهُ في التَّعريف، والتَّنكير.
الأمثلة :
نجحَ أخوك هاشمٌ .                        أعرفُ أخاك هاشماً .
رأيت وَالِدَيْهِ أُمَّهُ وأَبَاه .                   اقْتَدِ بالفاروقِ عُمَرَ .
هؤلاء الطلابُ مجتهدون .                 هؤلاء الطالباتُ مجتهداتٌ .
البدلُ أربعةُ أنواعٍ ، هي :
1- بدلُ كُلٍّ من كُلٍّ ، نحو :  نجح أخوك هاشمٌ .
2- بدلُ بَعْضٍ منَ كلٍّ ، نحو :  أكلتُ الدَّجاجةَ نصفَها .
3- بدلُ اشْتِمَالٍ ، نحو :  نَفَعَنِي المعلمُ عِلْمُهُ .
4- بدلُ غَلَطٍ ، نحو :  أكلتُ خُبْزاً تَمْراً .', 13, 15, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '1' and sort_order = 9;

