insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'الإعرابُ التَّقْدِيرِيُّ
الأفعالُ التي تُعْرَبُ إعراباً تقديريّاً ، هي :
1- الفعل المضارع المعتلّ النَّاقص في حالة الرَّفع ، نحو : يَمْشِي . يَدْعُو . يَنْسَى .
علامة الرَّفع الضمة المقدَّرة منع من ظهورها الثَّقل في الياء ، والواو؛ والتَعَذُّر في الألف.
2- الفعل المضارع المعتلّ النَّاقص ( المعتلّ بالألف ) في حالة النَّصب ، نحو : لن أَنْسَى .
علامة النصب الفتحة المقدّرة منع من ظهورها التَّعَذُّر .
أما المعتل بالواو ، أو الياء فعلامته ظاهرة ، نحو : لن أدعوَ . لن أمشيَ .
3- الفعل المضارع الْمُضَعَّف في حالة الجزم ، نحو : لم أَحُجَّ .
علامة الجزم سكون مقدَّر منع من ظهوره الْتِقَاء السَّاكنين ؛ لأن الأصل :لم أَحُجْجْ .', 17, 17, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '1' and sort_order = 11;

  select count(*) into new_rule_count
